@bp.route("/grep_processes")
def grep_processes():
    import subprocess
    name = request.args.get("name")
    if not name:
        return jsonify({"error": "no name provided"})
    ps = subprocess.run(["ps", "aux"], capture_output=True)
    if ps.stdout is None:
        return jsonify({"error": "no stdout returned"})
    grep = subprocess.run(["grep", name], input=ps.stdout, capture_output=True)
    awk = subprocess.run(["awk", "{print $11}"], input=grep.stdout, capture_output=True)
    if awk.stdout is None:
        return jsonify({"error": "no stdout returned"})
    out = awk.stdout.decode("utf-8")
    names = [line for line in out.split("\n") if line]
    return jsonify({"success": True, "names": names})
